r = primitives.call(name='observe_robotwin2_visual', camera_name='head_camera', query='three ranking blocks on table')
print('vis', r.ok)
h = []
if r.ok:
    o = r.output
    for k in ['evidence_handles','handles','evidence_handle','handle']:
        if isinstance(o, dict) and k in o:
            h = o[k]; break
    print('keys', list(o.keys())[:12] if isinstance(o,dict) else type(o))
print('handles', h)

info = {}
for lab in ['block1', 'block2', 'block3']:
    r = primitives.call(name='measure_robotwin2_actor_visual', actor_label=lab,
                        camera_name='head_camera', depth_scale=1.0, max_points=300)
    print(lab, r.ok)
    if r.ok:
        o = r.output
        for k in ['mask_pixel_count', 'point_count', 'center_world', 'centroid_world',
                  'bbox_world', 'extent', 'extents', 'size', 'dims', 'bounds_min',
                  'bounds_max', 'evidence_handles']:
            if k in o:
                v = o[k]
                if isinstance(v, list):
                    v = [round(x, 3) if isinstance(x, float) else x for x in v]
                print('   ', k, v)
        info[lab] = o
        print('    keys:', [k for k in o.keys()][:20])

for lab in ['block1','block2','block3']:
    o = info[lab]
    pts = o.get('world_points')
    print(lab, 'n', o.get('world_point_count'), 'pose', [round(v,4) for v in o.get('pose_world')[:3]])
